<?php
require_once __DIR__.'/../includes/functions.php';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$collection=(int)($_POST['id_collection']??0);$category=(int)($_POST['id_category']??0);$title=trim($_POST['title']??'');$content=trim($_POST['content']??'');$check=db()->prepare('SELECT COUNT(*) FROM crs_collection WHERE id_collection=?');$check->execute([$collection]);if(!$check->fetchColumn()||!$title||!$content){$err='Lengkapi koleksi, judul, dan isi diskusi.';}else{[$member,$staff]=actor_fields(current_user());$s=db()->prepare('INSERT INTO crs_topic(id_collection,id_category,member_id,user_id,title,content) VALUES(?,?,?,?,?,?)');$s->execute([$collection,$category,$member,$staff,$title,$content]);flash('Topik diskusi berhasil dibuat.');header('Location: '.crs_url('detail_topic').'&id='.db()->lastInsertId());exit;}}
$collections=db()->query('SELECT * FROM crs_collection ORDER BY title')->fetchAll();$categories=db()->query('SELECT * FROM crs_category ORDER BY category_name')->fetchAll();page_header('Mulai Diskusi'); ?>
<div class="narrow"><a class="back" href="<?=e(crs_url())?>">← Kembali ke diskusi</a><div class="eyebrow">MULAI PERCAKAPAN</div><h1>Buat topik diskusi</h1><p class="muted">Pilih koleksi yang ingin dibahas agar percakapan tetap terhubung dengan bahan pustaka.</p><?php if($err):?><div class="alert danger"><?=e($err)?></div><?php endif;?><form class="form-card" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Koleksi yang dibahas</label><select name="id_collection" required><option value="">Pilih koleksi</option><?php foreach($collections as $c):?><option value="<?=$c['id_collection']?>"><?=e($c['title'])?> — <?=e($c['author'])?></option><?php endforeach;?></select><label>Kategori diskusi</label><select name="id_category" required><?php foreach($categories as $c):?><option value="<?=$c['id_category']?>"><?=e($c['category_name'])?></option><?php endforeach;?></select><label>Judul diskusi</label><input name="title" maxlength="255" required placeholder="Contoh: Bagaimana menerapkan gagasan utama buku ini?"><label>Isi diskusi</label><textarea name="content" rows="7" required placeholder="Tuliskan pertanyaan, ulasan, interpretasi, atau rekomendasi... "></textarea><div class="form-actions"><a class="btn outline" href="<?=e(crs_url())?>">Batal</a><button class="btn primary">Terbitkan Diskusi</button></div></form></div>
<?php page_footer();?>
